  "Brød": "Bread",
  "Toast": "Toast",
  "Karamell": "Caramel",
  "Honning": "Honey",
  "Nøtter": "Nuts",
  "Sjokolade": "Chocolate",
  "Kaffe": "Coffee",
  "Røyk": "Smoke",
  "Bitterhet": "Bitterness",
  "Furunål": "Pine",
  "Jordlig": "Earthy",
  "Krydder": "Spice",
  "Sitrus": "Citrus",
  "Tropisk": "Tropical",
  "Fruktighet": "Fruitiness",
  "Steinfrukt": "Stone fruit",
